CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,name TEXT NOT NULL,base_url TEXT NOT NULL,adapter TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1,configuration TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,updated_at TEXT NOT NULL,last_sync_at TEXT,last_sync_status TEXT,last_error TEXT);
CREATE TABLE IF NOT EXISTS videos(id TEXT PRIMARY KEY,source_id TEXT NOT NULL,external_id TEXT NOT NULL,title TEXT NOT NULL,description TEXT,thumbnail_url TEXT,original_url TEXT NOT NULL,creator TEXT,duration INTEGER,view_count INTEGER,published_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,download_url TEXT,download_allowed INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(source_id) REFERENCES sources(id),UNIQUE(source_id,external_id));
CREATE TABLE IF NOT EXISTS downloads(id TEXT PRIMARY KEY,video_id TEXT NOT NULL,download_url TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(video_id) REFERENCES videos(id));
CREATE INDEX IF NOT EXISTS idx_videos_published ON videos(published_at DESC);CREATE INDEX IF NOT EXISTS idx_videos_source ON videos(source_id);CREATE INDEX IF NOT EXISTS idx_videos_creator ON videos(creator);CREATE INDEX IF NOT EXISTS idx_videos_title ON videos(title);
